const input = $input.first().json;

const document_id = String(input.document_id ?? '').trim();
const store_id = String(input.store_id ?? '').trim();

if (!document_id) {
  throw new Error('document_id가 없습니다.');
}

if (!store_id) {
  throw new Error('store_id가 없습니다.');
}

return [
  {
    json: {
      ...input,
      document_id,
      store_id
    }
  }
];

const results = [];

// 프로모션 기본 정보
const promotion = $('Get Promotion Data').first().json;

// Build Targeting Rules의 구조화 결과
const rules = $('Resolve Targeting Rules').first().json.output ?? {};


// 배열 또는 문자열을 검색 가능한 문자열로 변환
function toText(value) {
  if (value == null) return '';

  if (Array.isArray(value)) {
    return value.join(' ');
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}


// 대소문자 무시
function normalize(value) {
  return toText(value).toLowerCase().trim();
}


// 키워드가 하나라도 포함되는지 검사
function containsAny(text, keywords) {
  if (!Array.isArray(keywords) || keywords.length === 0) {
    return true;
  }

  const normalizedText = normalize(text);

  return keywords.some(keyword => {
    const k = normalize(keyword);
    return k && normalizedText.includes(k);
  });
}


// 공백 제거 + 소문자
function compact(value) {
  return toText(value).toLowerCase().replace(/\s+/g, '');
}


// 대부분의 고객에게 해당해서 대상을 가르지 못하는 말
const GENERIC_KEYWORDS = [
  '기기변경', '구매', '상담', '휴대폰', '스마트폰', '핸드폰',
  '프로모션', '요금제', '할인', '혜택', '변경', '교체', '고객', '신규', '가입'
];

function isGenericKeyword(keyword) {
  const k = compact(keyword).replace(/관심|희망|예정/g, '');
  return k.length < 2 || GENERIC_KEYWORDS.some(g => k === g || k === g + '고객');
}


// 같은 브랜드·제품군의 한글/영문 표기
const ALIAS_GROUPS = [
  ['iphone', '아이폰', 'apple', '애플'],
  ['galaxy', '갤럭시', 'samsung', '삼성'],
  ['fold', '폴드'],
  ['flip', '플립'],
  ['watch', '워치']
];

// 키워드 중 하나라도 텍스트에 있으면 그 키워드를 돌려준다.
// useAliases가 true면 "iPhone 17" 같은 기기명을 브랜드 표기(아이폰, Apple 등)로도 찾는다.
function findKeyword(text, keywords, useAliases) {
  for (const keyword of keywords) {
    const k = compact(keyword);
    if (!k) continue;

    if (text.includes(k)) return String(keyword);

    if (!useAliases) continue;

    for (const group of ALIAS_GROUPS) {
      if (!group.some(alias => k.includes(alias))) continue;

      const alias = group.find(candidate => text.includes(candidate));
      // 사유에는 고객 글에서 찾은 표기 대신 프로모션의 대상 기기 이름을 보여 준다.
      if (alias) return String(keyword);
    }
  }

  return null;
}


for (const item of $input.all()) {
  const customer = item.json;
  const analysis = customer.analysis_data ?? {};

  let matched = true;
  const matchReasons = [];

  // --------------------------------
  // 1. 최소 나이
  // --------------------------------
  if (rules.age_min != null) {
    if (
      customer.age == null ||
      Number(customer.age) < Number(rules.age_min)
    ) {
      matched = false;
    } else {
      matchReasons.push(`최소 연령 ${rules.age_min}세 이상 충족`);
    }
  }

  // --------------------------------
  // 2. 최대 나이
  // --------------------------------
  if (rules.age_max != null) {
    if (
      customer.age == null ||
      Number(customer.age) > Number(rules.age_max)
    ) {
      matched = false;
    } else {
      matchReasons.push(`최대 연령 ${rules.age_max}세 이하 충족`);
    }
  }

  // --------------------------------
  // 3. 최소 기기 사용 기간
  // --------------------------------
  if (rules.min_device_use_months != null) {
    if (
      customer.device_use_months == null ||
      Number(customer.device_use_months) <
        Number(rules.min_device_use_months)
    ) {
      matched = false;
    } else {
      matchReasons.push(
        `기기 사용 ${rules.min_device_use_months}개월 이상 충족`
      );
    }
  }

  // --------------------------------
  // 4. 고객의 관심/분석 데이터 통합
  // --------------------------------
  const interestText = [
    customer.interests,
    customer.consultation_goal,
    customer.usage_pattern,
    customer.preferred_brand,

    analysis.analysis_summary,
    analysis.replacement_reason,
    analysis.preferred_product_group,
    analysis.important_features,
    analysis.recommendation_factors
  ]
    .filter(v => v != null)
    .map(toText)
    .join(' ');


  // --------------------------------
  // 5. 프로모션 대상 기기 / 관심 조건
  // --------------------------------
  // 대상 기기가 명시된 프로모션은 그 기기(또는 같은 브랜드)에 관심을 보인 고객만 대상으로 한다.
  // "기기변경", "구매"처럼 대부분의 고객에게 해당하는 말은 조건으로 쓰지 않는다.
  const deviceKeywords = Array.isArray(rules.target_device_keywords)
    ? rules.target_device_keywords
    : [];

  const interestKeywords = (Array.isArray(rules.interest_keywords)
    ? rules.interest_keywords
    : []
  ).filter(keyword => !isGenericKeyword(keyword));

  // 고객의 관심을 판단할 전체 텍스트
  const targetingText = compact([
    customer.interests,
    customer.consultation_goal,
    customer.usage_pattern,
    customer.preferred_brand,

    analysis.analysis_summary,
    analysis.usage_profile,
    analysis.replacement_reason,
    analysis.preferred_product_group,
    analysis.important_features,
    analysis.recommendation_factors
  ]
    .filter(v => v != null)
    .map(toText)
    .join(' '));

  if (deviceKeywords.length > 0) {
    const hit = findKeyword(targetingText, deviceKeywords, true);

    if (!hit) {
      matched = false;
    } else {
      matchReasons.push(`대상 기기 관심 조건 충족 (${hit})`);
    }
  } else if (interestKeywords.length > 0) {
    const hit = findKeyword(targetingText, interestKeywords, false);

    if (!hit) {
      matched = false;
    } else {
      matchReasons.push(`관심 조건 충족 (${hit})`);
    }
  }


  // --------------------------------
  // 7. 선호 브랜드
  // --------------------------------
  if (
    Array.isArray(rules.preferred_brand_keywords) &&
    rules.preferred_brand_keywords.length > 0
  ) {
    const brandText = [
      customer.preferred_brand,
      analysis.preferred_product_group
    ]
      .filter(Boolean)
      .join(' ');

    const found = containsAny(
      brandText,
      rules.preferred_brand_keywords
    );

    if (!found) {
      matched = false;
    } else {
      matchReasons.push('선호 브랜드 조건 충족');
    }
  }


  // --------------------------------
  // 8. 대상 요금제
  // --------------------------------
  if (
    Array.isArray(rules.target_plan_keywords) &&
    rules.target_plan_keywords.length > 0
  ) {
    const found = containsAny(
      customer.current_plan,
      rules.target_plan_keywords
    );

    if (!found) {
      matched = false;
    } else {
      matchReasons.push('대상 요금제 조건 충족');
    }
  }


  // 하나라도 필수 조건 불일치
  if (!matched) {
    continue;
  }


  // --------------------------------
  // 최종 대상 고객
  // --------------------------------
  results.push({
    json: {
      customer_id: customer.customer_id,
      customer_name: customer.customer_name,
      phone: customer.phone,

      schedule_type: 'promotion',

      reference_date:
        promotion.valid_from ?? null,

      contact_reason:
        `${promotion.file_name || '프로모션'} 안내`,

      document_id:
        promotion.document_id ?? null,

      store_id:
        promotion.store_id ?? null,

      consultation_id: null,

      match_reasons: matchReasons,

      eligibility_notes:
        Array.isArray(rules.eligibility_notes)
          ? rules.eligibility_notes
          : []
    }
  });
}

return results;

const items = $input.all();

const seen = new Set();
const results = [];

for (const item of items) {
  const customer = item.json;

  // 필수값 확인
  if (!customer.customer_id) {
    continue;
  }

  if (!customer.document_id) {
    continue;
  }

  if (!customer.schedule_type) {
    continue;
  }

  // 동일 고객 중복 제거
  if (seen.has(customer.customer_id)) {
    continue;
  }

  seen.add(customer.customer_id);

  results.push({
    json: {
      ...customer
    }
  });
}

return results;

const input = $('Validate Promotion Input').first().json;

return [
  {
    json: {
      success: false,
      feature_id: 'F-06',
      status: 'promotion_not_found',
      document_id: input.document_id ?? null,
      store_id: input.store_id ?? null,
      target_count: 0,
      target_customers: []
    }
  }
];

const input = $input.first().json;

let rules = input.condition_data ?? {};

if (typeof rules === 'string') {
  try {
    rules = JSON.parse(rules);
  } catch {
    rules = {};
  }
}

return [
  {
    json: {
      output: rules,
      source: 'condition_data'
    }
  }
];

const promotion = $('Get Promotion Data').first().json;

const text = $input.all()
  .map((item) => item.json.document?.pageContent ?? item.json.pageContent ?? '')
  .filter(Boolean)
  .join('\n\n');

return [
  {
    json: {
      ...promotion,
      promotion_condition_text: text,
      condition_source: 'rag',
    },
  },
];

const input = $input.first().json;

return [
  {
    json: {
      output: input.output ?? {},
      source: input.source ?? 'rag'
    }
  }
];

