return [
  {
    json: {
      success: false,
      feature_id: 'F-06',
      status: 'condition_not_found',
      message: '프로모션 조건을 확인할 문서가 등록되어 있지 않습니다.',
      document_id: promotion.document_id ?? null,
      store_id: promotion.store_id ?? null,
      target_count: 0,
      target_customers: [],
    },
  },
];
